package live.linghe.privateinput;
import java.util.*;import java.util.function.*;
/** Bounded port of the existing Swift syllable lattice, including swap recall. */
final class PinyinCorrector {
 static final class Proposal{final String spelling;final int edits;final double cost;Proposal(String s,int e,double c){spelling=s;edits=e;cost=c;}}
 private static final class Edge{final String text;final int edits;final double cost;Edge(String s,int e,double c){text=s;edits=e;cost=c;}}
 private static final class State{final String text;final int edits,parts;final double cost,prior;State(String s,int e,double c,int p,double prior){text=s;edits=e;cost=c;parts=p;this.prior=prior;}double score(){return cost+parts*.03-prior;}}
 private final Set<String> syllables;private final ToLongFunction<String> frequency;private final Map<String,List<Edge>> repairs=new HashMap<>();
 PinyinCorrector(Set<String> syllables,ToLongFunction<String> frequency){this.syllables=new HashSet<>(syllables);this.frequency=frequency;ArrayList<String> ordered=new ArrayList<>(syllables);Collections.sort(ordered);for(String syllable:ordered){int n=syllable.length();if(n<=1)continue;if(n>=3)for(int i=0;i<n-1;i++)for(int j=i+1;j<n;j++){String missing=syllable.substring(0,i)+syllable.substring(i+1,j)+syllable.substring(j+1);if(!missing.isEmpty())add(missing,new Edge(syllable,2,2));}for(int i=0;i<n;i++){String missing=syllable.substring(0,i)+syllable.substring(i+1);if(!missing.isEmpty())add(missing,new Edge(syllable,1,1));if(i+1<n&&syllable.charAt(i)!=syllable.charAt(i+1))add(swap(syllable,i),new Edge(syllable,1,1.1));}}}
 private void add(String key,Edge edge){repairs.computeIfAbsent(key,k->new ArrayList<>()).add(edge);}
 private static String swap(String text,int at){char[] chars=text.toCharArray();char c=chars[at];chars[at]=chars[at+1];chars[at+1]=c;return new String(chars);}
 private boolean valid(String text){boolean[] reachable=new boolean[text.length()+1];reachable[0]=true;for(int start=0;start<text.length();start++)if(reachable[start])for(int end=start+1;end<=Math.min(text.length(),start+6);end++)if(syllables.contains(text.substring(start,end)))reachable[end]=true;return reachable[text.length()];}
 List<Proposal> proposals(String input,int limit){return proposals(input,limit,()->false);}
 List<Proposal> proposals(String input,int limit,BooleanSupplier cancelled){int n=input.length();if(n<4||n>96||!input.matches("[a-z]+")||limit<=0)return Collections.emptyList();ArrayList<ArrayList<State>> lattice=new ArrayList<>();for(int i=0;i<=n;i++)lattice.add(new ArrayList<>());lattice.get(0).add(new State("",0,0,0,0));int maximum=n>=6?2:1;Comparator<State> rank=(a,b)->{int c=Double.compare(a.score(),b.score());return c!=0?c:a.text.compareTo(b.text);};
  for(int position=0;position<n;position++){if(cancelled.getAsBoolean())return Collections.emptyList();if(lattice.get(position).isEmpty())continue;for(int end=position+1;end<=Math.min(n,position+7);end++){String fragment=input.substring(position,end);ArrayList<Edge> edges=new ArrayList<>();if(syllables.contains(fragment))edges.add(new Edge(fragment,0,0));edges.addAll(repairs.getOrDefault(fragment,Collections.emptyList()));if(fragment.length()>1)for(int i=0;i<fragment.length();i++){String shorter=fragment.substring(0,i)+fragment.substring(i+1);if(syllables.contains(shorter))edges.add(new Edge(shorter,1,1.05));}if(edges.isEmpty())continue;
   for(State previous:lattice.get(position))for(Edge edge:edges){int edits=previous.edits+edge.edits;if(edits>maximum)continue;String text=previous.text+edge.text;State next=new State(text,edits,previous.cost+edge.cost,previous.parts+1,previous.prior+Math.log1p(frequency.applyAsLong(text))*.003);ArrayList<State> current=lattice.get(end);int found=-1;for(int i=0;i<current.size();i++)if(current.get(i).text.equals(text)&&current.get(i).edits==edits){found=i;break;}if(found>=0){if(current.get(found).score()<=next.score())continue;current.remove(found);}current.add(next);}
   ArrayList<State> kept=new ArrayList<>();for(int budget=0;budget<=maximum;budget++){ArrayList<State> values=new ArrayList<>();for(State state:lattice.get(end))if(state.edits==budget)values.add(state);values.sort(rank);kept.addAll(values.subList(0,Math.min(48,values.size())));}lattice.set(end,kept);
  }}
  ArrayList<State> ranked=new ArrayList<>();for(State state:lattice.get(n))if(state.edits>0&&!state.text.equals(input))ranked.add(state);ranked.sort(rank);ArrayList<Proposal> swaps=new ArrayList<>();Set<String> swapSeen=new HashSet<>();
  if(n<=24)for(int i=0;i<n-1;i++)if(input.charAt(i)!=input.charAt(i+1)){if(cancelled.getAsBoolean())return Collections.emptyList();String once=swap(input,i);if(!once.equals(input)&&swapSeen.add(once)&&valid(once))swaps.add(new Proposal(once,1,1.1));if(maximum>=2)for(int j=i+1;j<n-1;j++)if(once.charAt(j)!=once.charAt(j+1)){String twice=swap(once,j);if(!twice.equals(input)&&swapSeen.add(twice)&&valid(twice))swaps.add(new Proposal(twice,2,2.2));}}
  ArrayList<Proposal> deletions=new ArrayList<>();Set<String> deletionSeen=new HashSet<>();
  for(int i=0;i<n;i++){if(cancelled.getAsBoolean())return Collections.emptyList();String shorter=input.substring(0,i)+input.substring(i+1);if(deletionSeen.add(shorter)&&valid(shorter)){boolean repeated=(i>0&&input.charAt(i-1)==input.charAt(i))||(i+1<n&&input.charAt(i+1)==input.charAt(i));deletions.add(new Proposal(shorter,1,repeated?.9:1.05));}}
  deletions.sort((a,b)->{double x=Math.log1p(frequency.applyAsLong(a.spelling))-a.cost*1.5,y=Math.log1p(frequency.applyAsLong(b.spelling))-b.cost*1.5;int c=Double.compare(y,x);return c!=0?c:a.spelling.compareTo(b.spelling);});
  swaps.sort((a,b)->{double x=Math.log1p(frequency.applyAsLong(a.spelling))-a.edits*.2,y=Math.log1p(frequency.applyAsLong(b.spelling))-b.edits*.2;int c=Double.compare(y,x);return c!=0?c:a.spelling.compareTo(b.spelling);});int ceiling=Math.min(64,limit);ArrayList<Proposal> selected=new ArrayList<>();for(State state:ranked)if(state.edits==1&&selected.size()<Math.min(ceiling,32))selected.add(new Proposal(state.text,state.edits,state.cost));for(State state:ranked)if(state.edits==2&&selected.size()<Math.min(48,ceiling))selected.add(new Proposal(state.text,state.edits,state.cost));for(Proposal deletion:deletions.subList(0,Math.min(4,deletions.size()))){int found=-1;for(int i=0;i<selected.size();i++)if(selected.get(i).spelling.equals(deletion.spelling)){found=i;break;}if(found>=0){if(deletion.cost<selected.get(found).cost)selected.set(found,deletion);}else if(selected.size()<ceiling)selected.add(deletion);}for(Proposal proposal:swaps)if(selected.size()<ceiling&&!contains(selected,proposal.spelling))selected.add(proposal);for(State state:ranked)if(selected.size()<ceiling&&!contains(selected,state.text))selected.add(new Proposal(state.text,state.edits,state.cost));ArrayList<Proposal> result=new ArrayList<>();Set<String> seen=new HashSet<>();for(Proposal value:selected)if(seen.add(value.spelling))result.add(value);return result;
 }
 private boolean contains(List<Proposal> values,String text){for(Proposal value:values)if(value.spelling.equals(text))return true;return false;}
}
